import{_ as r,C as n,o as a,c as s,a2 as t,b as c,w as o,a as d,E as l,a3 as u}from"./chunks/framework.CgxQ0r6v.js";const C=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 2","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_III/documentacion/III-VII/Lectura_Catedra_Evaluacion_2.md","filePath":"materias/Proyecto_Sociotecnologico_III/documentacion/III-VII/Lectura_Catedra_Evaluacion_2.md"}'),g={name:"materias/Proyecto_Sociotecnologico_III/documentacion/III-VII/Lectura_Catedra_Evaluacion_2.md"};function p(m,e,f,I,y,h){const i=n("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="manual-de-estudio-profundo-evaluacion-2" tabindex="-1">Manual de Estudio Profundo: Evaluación 2 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-2" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 2&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-iii-trayecto-iii-trimestre-vii" tabindex="-1">Materia: Proyecto Sociotecnológico III (Trayecto III - Trimestre VII) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-iii-trayecto-iii-trimestre-vii" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico III (Trayecto III - Trimestre VII)&quot;">​</a></h2><h3 id="eje-tematico-planteamiento-del-proyecto-gestion-de-riesgos-y-factores-de-exito" tabindex="-1">Eje Temático: Planteamiento del Proyecto, Gestión de Riesgos y Factores de Éxito <a class="header-anchor" href="#eje-tematico-planteamiento-del-proyecto-gestion-de-riesgos-y-factores-de-exito" aria-label="Permalink to &quot;Eje Temático: Planteamiento del Proyecto, Gestión de Riesgos y Factores de Éxito&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-gestion-proactiva-de-la-incertidumbre" tabindex="-1">🧭 Introducción: La Gestión Proactiva de la Incertidumbre <a class="header-anchor" href="#🧭-introduccion-la-gestion-proactiva-de-la-incertidumbre" aria-label="Permalink to &quot;🧭 Introducción: La Gestión Proactiva de la Incertidumbre&quot;">​</a></h2><p>En proyectos de software de mediana y gran escala, el fracaso rara vez ocurre por sorpresa; ocurre por <strong>riesgos conocidos que fueron ignorados durante la planificación</strong>.</p><p>Un apagón prolongado que quema el único disco duro del servidor comunitario, un cambio intempestivo de la directiva de la institución que desconoce el proyecto, o la renuncia de un miembro clave del equipo de desarrollo son situaciones comunes en nuestro contexto. La ingeniería de proyectos exige <strong>anticipar los riesgos, cuantificar su gravedad y diseñar planes de contingencia antes de que ocurran</strong>.</p><hr><h2 id="⚠️-capitulo-i-identificacion-y-clasificacion-de-riesgos" tabindex="-1">⚠️ CAPÍTULO I: Identificación y Clasificación de Riesgos <a class="header-anchor" href="#⚠️-capitulo-i-identificacion-y-clasificacion-de-riesgos" aria-label="Permalink to &quot;⚠️ CAPÍTULO I: Identificación y Clasificación de Riesgos&quot;">​</a></h2><p>En el PST III, los riesgos se clasifican en cuatro categorías principales:</p>',10)),(a(),c(u,null,{default:o(()=>[l(i,{id:"mermaid-26",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20R%5B%22%E2%9A%A0%EF%B8%8F%20Categor%C3%ADas%20de%20Riesgo%20en%20PST%20III%22%5D%0A%20%20%20%20R%20--%3E%20RT%5B%22%F0%9F%92%BB%20Riesgos%20T%C3%A9cnicos%3A%20Obsolescencia%20de%20hardware%2C%20fallas%20de%20conectividad%2C%20bugs%20cr%C3%ADticos%22%5D%0A%20%20%20%20R%20--%3E%20RO%5B%22%F0%9F%91%A5%20Riesgos%20Operativos%20%2F%20Humanos%3A%20Resistencia%20al%20cambio%2C%20falta%20de%20capacitaci%C3%B3n%2C%20rotaci%C3%B3n%20de%20personal%22%5D%0A%20%20%20%20R%20--%3E%20RG%5B%22%F0%9F%8F%9B%EF%B8%8F%20Riesgos%20Organizacionales%20%2F%20Pol%C3%ADticos%3A%20Cambios%20de%20autoridades%2C%20falta%20de%20presupuesto%20o%20insumos%22%5D%0A%20%20%20%20R%20--%3E%20RE%5B%22%E2%9A%A1%20Riesgos%20del%20Entorno%3A%20Cortes%20de%20suministro%20el%C3%A9ctrico%2C%20fluctuaciones%20de%20voltaje%22%5D%0A%0A%20%20%20%20style%20R%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20RT%20fill%3A%237c2d12%2Cstroke%3A%23ea580c%2Ccolor%3A%23fff%0A%20%20%20%20style%20RO%20fill%3A%23b45309%2Cstroke%3A%23f59e0b%2Ccolor%3A%23fff%0A%20%20%20%20style%20RG%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A%20%20%20%20style%20RE%20fill%3A%230369a1%2Cstroke%3A%230ea5e9%2Ccolor%3A%23fff%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<hr><h2 id="📊-capitulo-ii-la-matriz-de-evaluacion-de-riesgos-probabilidad-e-impacto" tabindex="-1">📊 CAPÍTULO II: La Matriz de Evaluación de Riesgos (Probabilidad e Impacto) <a class="header-anchor" href="#📊-capitulo-ii-la-matriz-de-evaluacion-de-riesgos-probabilidad-e-impacto" aria-label="Permalink to &quot;📊 CAPÍTULO II: La Matriz de Evaluación de Riesgos (Probabilidad e Impacto)&quot;">​</a></h2><p>Para priorizar qué riesgos requieren atención inmediata, se utiliza una escala estándar de 1 a 5: $$\\text{Nivel de Riesgo} = \\text{Probabilidad} \\times \\text{Impacto}$$</p><table tabindex="0"><thead><tr><th>ID</th><th>Descripción del Evento de Riesgo</th><th style="text-align:center;">Probabilidad (1-5)</th><th style="text-align:center;">Impacto (1-5)</th><th style="text-align:center;">Nivel (PxI)</th><th>Estrategia de Mitigación / Contingencia</th></tr></thead><tbody><tr><td><strong>R-01</strong></td><td>Fluctuaciones eléctricas que provoquen corrupción de la base de datos.</td><td style="text-align:center;"><strong>5 (Muy Alta)</strong></td><td style="text-align:center;"><strong>5 (Catastrófico)</strong></td><td style="text-align:center;"><strong>25 (Crítico)</strong></td><td>Conectar el servidor a UPS; configurar motor transaccional con journaling/WAL y respaldos automáticos cada hora.</td></tr><tr><td><strong>R-02</strong></td><td>Resistencia de los operadores a sustituir los libros de papel por el sistema.</td><td style="text-align:center;"><strong>4 (Alta)</strong></td><td style="text-align:center;"><strong>4 (Mayor)</strong></td><td style="text-align:center;"><strong>16 (Alto)</strong></td><td>Talleres de sensibilización desde la fase de diseño; hacerlos partícipes activos y diseñar interfaces simplificadas.</td></tr><tr><td><strong>R-03</strong></td><td>Pérdida del código fuente por daño en la computadora de un estudiante.</td><td style="text-align:center;"><strong>3 (Media)</strong></td><td style="text-align:center;"><strong>5 (Catastrófico)</strong></td><td style="text-align:center;"><strong>15 (Alto)</strong></td><td>Uso obligatorio de repositorio Git remoto institucional con sincronización diaria de ramas.</td></tr><tr><td><strong>R-04</strong></td><td>Renuncia o traslado de la autoridad institucional que aprobó el proyecto.</td><td style="text-align:center;"><strong>3 (Media)</strong></td><td style="text-align:center;"><strong>3 (Moderado)</strong></td><td style="text-align:center;"><strong>9 (Medio)</strong></td><td>Protocolización del proyecto mediante Acta de Consejo Directivo institucional para que trascienda a las personas.</td></tr></tbody></table><hr><h2 id="🌟-capitulo-iii-factores-criticos-de-exito-del-proyecto" tabindex="-1">🌟 CAPÍTULO III: Factores Críticos de Éxito del Proyecto <a class="header-anchor" href="#🌟-capitulo-iii-factores-criticos-de-exito-del-proyecto" aria-label="Permalink to &quot;🌟 CAPÍTULO III: Factores Críticos de Éxito del Proyecto&quot;">​</a></h2><p>Los <strong>Factores de Éxito</strong> son los elementos clave que deben cumplirse para garantizar que la solución informática no solo se entregue, sino que genere valor real y duradero:</p><ol><li><strong>Compromiso y Liderazgo Institucional:</strong> Respaldado con firmas en actas y asignación de tiempo a los operadores para capacitarse.</li><li><strong>Adopción de Tecnologías Libres Maduras:</strong> Elección de pilas de software estables (Linux, PostgreSQL, frameworks consolidados) con abundante documentación y soporte comunitario.</li><li><strong>Diseño Centrado en el Usuario (UCD):</strong> Reducción de la fricción cognitiva mediante interfaces intuitivas que minimicen la cantidad de clics necesarios para completar una transacción.</li><li><strong>Capacitación Efectiva y Material Didáctico:</strong> Entrega de manuales claros y realización de simulaciones prácticas antes de la puesta en marcha definitiva.</li></ol><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-2" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 2 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-2" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 2&quot;">​</a></h2><p>Para la Evaluación 2 del Trimestre VII:</p><ol><li><strong>Matriz de Riesgos y Plan de Contingencia:</strong> Documentada en el informe de proyecto con planes de mitigación concretos.</li><li><strong>Definición de Factores Críticos de Éxito:</strong> Indicadores cuantitativos que medirán el impacto positivo del sistema.</li><li><strong>Planteamiento del Problema Consolidado:</strong> Respaldado con la evidencia empírica recolectada en la comunidad.</li></ol>',12))])}const A=r(g,[["render",p]]);export{C as __pageData,A as default};
